function fdcIsHomebrewCampaign(name){return name===SPIES.name||name===HERITAGE.name||name===EMERAUDE.name;}
function fdcIsHomebrew(){return fdcIsHomebrewCampaign(state.campaign);}
function fdcSpiesCombat(){
 fdcHomeMonsterLibrary();
 const campaign=state.campaign===EMERAUDE.name?EMERAUDE:state.campaign===HERITAGE.name?HERITAGE:SPIES;
 const combatKey=campaign===EMERAUDE?'fdc-combat-emeraude-v1':campaign===HERITAGE?'fdc-combat-heritage-v1':'fdc-combat-spies-v1';
 let doc=embeddedCombat.replace("const KEY='fdc-combat-v12-demo-3'","const KEY="+JSON.stringify(combatKey));
 const start=doc.indexOf('const defaults=()=>('),end=doc.indexOf(';try{state=',start);
 doc=doc.slice(0,start)+'const defaults=()=>('+JSON.stringify(campaign.combat)+')'+doc.slice(end);
 doc=doc.replace("const LIBKEY='fdc-global-monster-library-v1'","const LIBKEY='fdc-homebrew-monster-library-v1'");
 doc=doc.replace(/const fdcOneShotMonsters=\[[\s\S]*?\];/,'const fdcOneShotMonsters=[];');
 doc=doc.replaceAll('La Nuit des Morts-Vivants',campaign.name);
 doc=doc.replace('Les fiches du PDF fourni et les fiches de campagne sont partagées entre tes campagnes.','Les fiches de ton mode maison sont partagées entre ses campagnes.');
 const extra=`<script>
 for(const portrait of ${JSON.stringify(campaign!==SPIES?campaign.combat.pj.map(({id,photo})=>({id,photo})):[])}){
  const player=state.pj.find(p=>p.id===portrait.id);
  if(player&&!player.photo)player.photo=portrait.photo;
 }
 const basePJCard=fdcPJCard;
 fdcPJCard=p=>basePJCard(p).replace('</div></div>', '<button class="small" onclick="fdcShowPJRules(this.dataset.id)" data-id="'+esc(p.id)+'">Fiche</button></div></div>');
 function fdcShowPJRules(id){const p=state.pj.find(x=>x.id===id);openModal('Fiche · '+p.name,'<p>'+esc(p.description||'')+'</p><p style="white-space:pre-wrap">'+esc(p.abilities||'')+'</p>',()=>closeModal());}

 render();
 <\/script>`;
 return fdcWithLibrary(fdcHomeCombatStats(doc)).replace('</body>',extra+'</body>');
}
function fdcShowHomebrewInfo(){
 let info=document.getElementById('homebrewInfo');
 if(!info){info=document.createElement('dialog');info.id='homebrewInfo';info.className='dialog';document.body.append(info);}
 info.innerHTML='<h3>Info · Règles maison</h3><p>1D20 + Force (contact), Adresse (projectiles) ou Esprit (magie), contre la CA. Puis dégâts de l’attaque. Initiative dynamique.</p><div class="tabs"><button id="homebrewSpells">Sorts maison</button><button id="homebrewMonsters">Bestiaire maison</button></div><input id="homebrewSearch" type="search" placeholder="Rechercher…"><div id="homebrewResults"></div><button id="homebrewClose">Fermer</button>';
 let tab='spells';
 function render(){
  let entries=[];try{entries=tab==='spells'?fdcHomeSpellLibrary():fdcHomeMonsterLibrary()}catch(e){}
  const q=info.querySelector('input').value.toLocaleLowerCase('fr');
  const results=info.querySelector('#homebrewResults');results.replaceChildren();
  const matches=entries.filter(x=>JSON.stringify(x).toLocaleLowerCase('fr').includes(q));
  if(!matches.length){const empty=document.createElement('p');empty.className='muted';empty.textContent=tab==='spells'?'Aucun sort trouvé.':'Aucun monstre trouvé.';results.append(empty);}
  for(const entry of matches){
   const details=document.createElement('details');details.className='homebrew-entry';
   const summary=document.createElement('summary');summary.textContent=entry.name;summary.style.cssText='cursor:pointer;min-height:48px;padding:12px 8px;touch-action:manipulation';details.append(summary);
   const body=document.createElement('div');body.style.cssText='padding:0 12px 12px;white-space:pre-wrap;line-height:1.6';
   body.textContent=entry.abilities||entry.description||(entry.paragraphs||[]).join('\\n');details.append(body);results.append(details);
  }
 }
 info.querySelector('#homebrewSpells').onclick=()=>{tab='spells';render()};info.querySelector('#homebrewMonsters').onclick=()=>{tab='monsters';render()};info.querySelector('input').oninput=render;info.querySelector('#homebrewClose').onclick=()=>info.close();render();info.showModal();
}

