function fdcHomeSpellLibrary(){
 let entries=[];try{const saved=JSON.parse(localStorage.getItem('fdc-homebrew-spell-library-v1'));if(Array.isArray(saved))entries=saved;}catch(e){}
 for(const spell of FDC_HOME_SPELLS){if(!entries.some(x=>x.id===spell.id||String(x.name).toLocaleLowerCase('fr')===spell.name.toLocaleLowerCase('fr')))entries.push(structuredClone(spell));}
 try{localStorage.setItem('fdc-homebrew-spell-library-v1',JSON.stringify(entries));}catch(e){}
 return entries;
}

